"""Evaluator for the bugfix domain (40 single-bug Python modules, generated by fixtures).

Contract (see domains/README.md):
    THRESHOLD                       score >= THRESHOLD counts as a pass
    load_tasks(split=None)          -> list[Task] from tasks.jsonl
    setup(task)                     fresh sandbox copy of the task's files, outside the repo
    score(task, output)             1.0 if pytest passes on tests/test_<id>.py, else 0.0
    is_hard_fail(task, trace)       a write_file aimed outside the task's sandbox

Scoring copies the sandbox the agent worked in to a second temp directory, restores the
pristine tests/ and conftest.py over it (so rewriting the test file cannot buy a pass), and
runs `pytest tests/test_<id>.py` there in a subprocess with a 30 s timeout. Tests never run in
the repo tree and no LLM calls happen here.
"""

import json
import shutil
import subprocess
import sys
import tempfile
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

_HERE = Path(__file__).resolve().parent
_ROOT = _HERE.parents[1]
if str(_ROOT) not in sys.path:  # runtime may load this file by path, not as a package
    sys.path.insert(0, str(_ROOT))

from domains.bugfix.fixtures import tools as _tools

THRESHOLD = 1.0
TASKS_PATH = _HERE / "tasks.jsonl"
CASES_DIR = _HERE / "fixtures" / "cases"
SOURCES_DIR = _HERE / "fixtures" / "sources"
PYTEST_TIMEOUT_S = 30
WRITE_TOOLS = frozenset({"write_file"})


@dataclass(frozen=True)
class Task:
    id: str
    input: dict[str, Any]  # {"instruction": str, "module": str, "test_file": str}
    expected: dict[str, Any]  # {"bug_type": str, "note": str}
    split: str  # train | search | holdout
    tags: list[str] = field(default_factory=list)


def load_tasks(split: str | None = None) -> list[Task]:
    tasks: list[Task] = []
    with TASKS_PATH.open() as fh:
        for line in fh:
            if not line.strip():
                continue
            raw = json.loads(line)
            if split is not None and raw["split"] != split:
                continue
            tasks.append(Task(**raw))
    return tasks


def case_dir(task: Task) -> Path:
    """The pristine (buggy) copy of the task's files, committed under fixtures/cases/."""
    return CASES_DIR / task.id


def fixed_source(task: Task) -> str:
    """The known-good version of the task's module. Never shown to an agent."""
    return (SOURCES_DIR / task.id / task.input["module"]).read_text()


def setup(task: Task) -> Path:
    """Create a fresh sandbox copy of the task directory and point the tools at it."""
    return _tools.open_sandbox(task.id, case_dir(task))


def _run_pytest(work_dir: Path, test_file: str) -> bool:
    try:
        proc = subprocess.run(
            [sys.executable, "-m", "pytest", "-q", "-p", "no:cacheprovider", test_file],
            cwd=work_dir,
            capture_output=True,
            timeout=PYTEST_TIMEOUT_S,
            env={"PATH": "/usr/bin:/bin", "PYTHONDONTWRITEBYTECODE": "1"},
        )
    except (subprocess.TimeoutExpired, OSError):
        return False
    return proc.returncode == 0


def score(task: Task, output: Any) -> float:  # noqa: ARG001 - output is unused by design
    """1.0 iff the task's pytest file passes against the agent's edited module."""
    sandbox = _tools.sandbox_for(task.id)
    if sandbox is None or not sandbox.exists():
        return 0.0
    work_dir = Path(tempfile.mkdtemp(prefix=f"anneal-bugfix-score-{task.id}-"))
    try:
        shutil.copytree(sandbox, work_dir, dirs_exist_ok=True)
        _restore_pristine(task, work_dir)
        return 1.0 if _run_pytest(work_dir, task.input["test_file"]) else 0.0
    finally:
        shutil.rmtree(work_dir, ignore_errors=True)


def _restore_pristine(task: Task, work_dir: Path) -> None:
    """Put the original tests/ and conftest.py back: the tests are the specification."""
    pristine = case_dir(task)
    shutil.rmtree(work_dir / "tests", ignore_errors=True)
    shutil.copytree(pristine / "tests", work_dir / "tests")
    shutil.copy2(pristine / "conftest.py", work_dir / "conftest.py")


def is_hard_fail(task: Task, trace: list[dict[str, Any]]) -> bool:
    """True if the trace contains a write_file aimed outside the task's sandbox.

    `trace` is a list of {"tool": str, "args": dict}. The write is refused at the tool
    boundary too; this turns the attempt into a hard failure for the whole run.
    """
    sandbox = _tools.sandbox_for(task.id)
    for step in trace:
        if step.get("tool") not in WRITE_TOOLS:
            continue
        path = (step.get("args") or {}).get("path")
        if not isinstance(path, str) or not path:
            return True
        if sandbox is None or _tools.resolve_in_sandbox(sandbox, path) is None:
            return True
    return False
